        private static System.Collections.Generic.Dictionary<string, int> ReadPlan()
        {
            var path = System.Environment.GetEnvironmentVariable("DGF_PLAN");
            if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path))
